 88	import com.loja.api.CheckoutRequest;
 89	import com.loja.database.Database;
 90	import com.loja.models.*;
 91	import com.loja.utils.MoneyUtils;
 92	import java.sql.SQLException;
 93	import java.util.*;
 94	import java.util.regex.Pattern;
