102	    public static ValidationError validateCheckoutRequest(CheckoutRequest req) throws SQLException {
103	        if (req.items == null || req.items.isEmpty()) {
104	            return new ValidationError("INVALID_ORDER", 422);
105	        }
106	
107	        if (req.customer == null || req.customer.cpf == null || req.customer.cpf.isEmpty() ||
108	            req.customer.email == null || req.customer.email.isEmpty()) {
109	            return new ValidationError("INVALID_ORDER", 422);
110	        }
111	
112	        Set<String> seenSkus = new HashSet<>();
113	        for (CheckoutRequest.OrderItemData item : req.items) {
114	            if (item.sku == null || item.sku.isEmpty() || item.quantity <= 0) {
115	                return new ValidationError("INVALID_ORDER", 422);
116	            }
117	            if (seenSkus.contains(item.sku)) {
118	                return new ValidationError("INVALID_ORDER", 422);
119	            }
120	            seenSkus.add(item.sku);
121	        }
122	
123	        for (CheckoutRequest.OrderItemData item : req.items) {
124	            Product product = ProductService.getProduct(item.sku);
125	            if (product == null) {
126	                return new ValidationError("UNKNOWN_PRODUCT", 422);
127	            }
128	            if (product.discontinued) {
129	                return new ValidationError("PRODUCT_DISCONTINUED", 422);
130	            }
131	            if (product.stock < item.quantity) {
132	                return new ValidationError("INSUFFICIENT_STOCK", 422);
133	            }
134	        }
135	
136	        if (req.clubTier == null || req.clubTier.isEmpty()) {
137	            return new ValidationError("INVALID_CLUB_TIER", 422);
138	        }
139	        try {
140	            Enums.ClubTier.valueOf(req.clubTier);
141	        } catch (IllegalArgumentException e) {
142	            return new ValidationError("INVALID_CLUB_TIER", 422);
143	        }
144	
145	        if (req.region == null || req.region.isEmpty()) {
146	            return new ValidationError("INVALID_REGION", 422);
147	        }
148	        try {
149	            Enums.Region.valueOf(req.region);
150	        } catch (IllegalArgumentException e) {
151	            return new ValidationError("INVALID_REGION", 422);
152	        }
153	
154	        if (req.zipCode == null || !ZIP_CODE_PATTERN.matcher(req.zipCode).matches()) {
155	            return new ValidationError("INVALID_ZIP_CODE", 422);
156	        }
157	
158	        if (req.shippingMethod == null || req.shippingMethod.isEmpty()) {
159	            return new ValidationError("INVALID_SHIPPING_METHOD", 422);
160	        }
161	        try {
162	            Enums.ShippingMethod.valueOf(req.shippingMethod);
163	        } catch (IllegalArgumentException e) {
164	            return new ValidationError("INVALID_SHIPPING_METHOD", 422);
165	        }
166	
167	        ValidationError shippingError = validateShippingMethod(req);
168	        if (shippingError != null) {
169	            return shippingError;
170	        }
171	
172	        if (req.paymentMethod == null || req.paymentMethod.isEmpty()) {
173	            return new ValidationError("INVALID_PAYMENT_METHOD", 422);
174	        }
175	        try {
176	            Enums.PaymentMethod.valueOf(req.paymentMethod);
177	        } catch (IllegalArgumentException e) {
178	            return new ValidationError("INVALID_PAYMENT_METHOD", 422);
179	        }
180	
181	        int installments = req.installments != null ? req.installments : 1;
182	        if (!isInstallmentsValid(req.paymentMethod, installments)) {
183	            return new ValidationError("INVALID_INSTALLMENTS", 422);
184	        }
185	
186	        if (req.coupon != null && !req.coupon.isEmpty() && !isCouponValid(req.coupon)) {
187	            return new ValidationError("INVALID_COUPON", 422);
188	        }
189	
190	        ValidationError couponError = validateCouponApplicability(req);
191	        if (couponError != null) {
192	            return couponError;
193	        }
194	
195	        ValidationError paymentError = validatePaymentMethod(req);
196	        if (paymentError != null) {
197	            return paymentError;
198	        }
199	
200	        return null;
201	    }
202	
203	    private static ValidationError validateShippingMethod(CheckoutRequest req) throws SQLException {
204	        Enums.ShippingMethod method = Enums.ShippingMethod.valueOf(req.shippingMethod);
205	
206	        if (method == Enums.ShippingMethod.COURIER) {
207	            double totalWeight = 0;
208	            for (CheckoutRequest.OrderItemData item : req.items) {
209	                Product product = ProductService.getProduct(item.sku);
210	                totalWeight += product.weightKg * item.quantity;
211	            }
212	            if (totalWeight > MAX_COURIER_WEIGHT) {
213	                return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
214	            }
215	        }
216	
217	        if (method == Enums.ShippingMethod.ECONOMY || method == Enums.ShippingMethod.EXPRESS) {
218	            String translogUrl = System.getenv("TRANSLOG_URL");
219	            if (translogUrl == null || translogUrl.isEmpty()) {
220	                return null;
221	            }
222	
223	            double totalWeight = 0;
224	            for (CheckoutRequest.OrderItemData item : req.items) {
225	                Product product = ProductService.getProduct(item.sku);
226	                totalWeight += product.weightKg * item.quantity;
227	            }
228	
229	            String service = method == Enums.ShippingMethod.ECONOMY ? "STD" : "EXP";
230	            int weightGrams = (int) (totalWeight * 1000);
231	
232	            TranslogResponse response = queryTranslog(translogUrl, req.zipCode, weightGrams, service);
233	            if (response == null) {
234	                return new ValidationError("CARRIER_UNAVAILABLE", 503);
235	            }
236	            if (response.error != null && response.error.equals("ZIP_NOT_SERVED")) {
237	                return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
238	            }
239	        }
240	
241	        return null;
242	    }
243	
244	    private static ValidationError validateCouponApplicability(CheckoutRequest req) throws SQLException {
245	        if (req.coupon == null || req.coupon.isEmpty()) {
246	            return null;
247	        }
248	
249	        double subtotal = 0;
250	        for (CheckoutRequest.OrderItemData item : req.items) {
251	            Product product = ProductService.getProduct(item.sku);
252	            subtotal += product.price * item.quantity;
253	        }
254	        subtotal = MoneyUtils.round(subtotal);
255	
256	        if (req.coupon.equals("WELCOME10")) {
257	            boolean isFirstPurchase = !hasCompletedOrder(req.customer.cpf);
258	            if (!isFirstPurchase) {
259	                return new ValidationError("COUPON_NOT_APPLICABLE", 422);
260	            }
261	        } else if (req.coupon.equals("MINUS50")) {
262	            if (subtotal < 300) {
263	                return new ValidationError("COUPON_NOT_APPLICABLE", 422);
264	            }
265	        } else if (req.coupon.equals("FREESHIPPING")) {
266	            if (req.shippingMethod.equals("STORE_PICKUP")) {
267	                return new ValidationError("COUPON_NOT_APPLICABLE", 422);
268	            }
269	        }
270	
271	        return null;
272	    }
273	
274	    private static ValidationError validatePaymentMethod(CheckoutRequest req) throws SQLException {
275	        if (req.paymentMethod.equals("BANK_SLIP")) {
276	            OrderSummary summary = calculateSummary(req);
277	            if (summary.finalTotal > 1000.0) {
278	                return new ValidationError("PAYMENT_METHOD_UNAVAILABLE", 422);
279	            }
280	        }
281	        return null;
282	    }
283	
284	    public static OrderSummary calculateSummary(CheckoutRequest req) throws SQLException {
285	        double subtotal = 0;
286	        for (CheckoutRequest.OrderItemData item : req.items) {
287	            Product product = ProductService.getProduct(item.sku);
288	            subtotal += product.price * item.quantity;
289	        }
290	        subtotal = MoneyUtils.round(subtotal);
291	
292	        double couponDiscount = 0;
293	        if (req.coupon != null && !req.coupon.isEmpty()) {
294	            couponDiscount = calculateCouponDiscount(req, subtotal);
295	            double maxDiscount = MoneyUtils.round(subtotal * MAX_DISCOUNT_PERCENTAGE);
296	            if (couponDiscount > maxDiscount) {
297	                couponDiscount = maxDiscount;
298	            }
299	        }
300	
301	        double shippingCost = 0;
302	        int deliveryDays = 0;
303	        ShippingInfo shippingInfo = calculateShipping(req);
304	        if (shippingInfo != null) {
305	            shippingCost = shippingInfo.cost;
306	            deliveryDays = shippingInfo.days;
307	        }
308	
309	        if (Enums.ClubTier.valueOf(req.clubTier) == Enums.ClubTier.GOLD &&
310	            !req.shippingMethod.equals("COURIER") &&
311	            !req.shippingMethod.equals("STORE_PICKUP")) {
312	            shippingCost = 0;
313	        }
314	
315	        double insurance = calculateInsurance(req, subtotal);
316	
317	        double totalBeforePayment = subtotal - couponDiscount + shippingCost + insurance;
318	        totalBeforePayment = MoneyUtils.round(totalBeforePayment);
319	
320	        double paymentAdjustment = 0;
321	        int installments = req.installments != null ? req.installments : 1;
322	        double finalTotal = totalBeforePayment;
323	
324	        if (req.coupon == null || req.coupon.isEmpty()) {
325	            if (req.paymentMethod.equals("PIX")) {
326	                double pixDiscount = MoneyUtils.round(totalBeforePayment * 0.05);
327	                paymentAdjustment = -pixDiscount;
328	                finalTotal = MoneyUtils.round(totalBeforePayment - pixDiscount);
329	            } else if (req.paymentMethod.equals("BANK_SLIP")) {
330	                paymentAdjustment = 3.49;
331	                finalTotal = MoneyUtils.round(totalBeforePayment + 3.49);
332	            }
333	        } else if (req.paymentMethod.equals("BANK_SLIP")) {
334	            paymentAdjustment = 3.49;
335	            finalTotal = MoneyUtils.round(totalBeforePayment + 3.49);
336	        }
337	
338	        double installmentAmount = finalTotal;
339	        if (req.paymentMethod.equals("CREDIT_CARD") && installments > 3) {
340	            double monthlyRate = 0.0199;
341	            double factor = Math.pow(1 + monthlyRate, -installments);
342	            installmentAmount = MoneyUtils.round(finalTotal * monthlyRate / (1 - factor));
343	            finalTotal = MoneyUtils.round(installmentAmount * installments);
344	        } else if (installments > 1) {
345	            installmentAmount = MoneyUtils.round(finalTotal / installments);
346	            finalTotal = MoneyUtils.round(installmentAmount * installments);
347	        }
348	
349	        double credit = 0;
350	        Enums.ClubTier tier = Enums.ClubTier.valueOf(req.clubTier);
351	        if (tier == Enums.ClubTier.SILVER) {
352	            credit = MoneyUtils.round(subtotal * 0.02);
353	        } else if (tier == Enums.ClubTier.GOLD) {
354	            credit = MoneyUtils.round(subtotal * 0.05);
355	        }
356	
357	        boolean gift = tier == Enums.ClubTier.GOLD && subtotal > 500;
358	
359	        return new OrderSummary(
360	            subtotal, couponDiscount, shippingCost, deliveryDays, insurance,
361	            paymentAdjustment, finalTotal, installments, installmentAmount,
362	            credit, gift
363	        );
364	    }
365	
366	    private static double calculateCouponDiscount(CheckoutRequest req, double subtotal) throws SQLException {
367	        String coupon = req.coupon;
368	
369	        if (coupon.equals("WELCOME10")) {
370	            boolean isFirstPurchase = !hasCompletedOrder(req.customer.cpf);
371	            if (!isFirstPurchase) {
372	                return 0;
373	            }
374	            return MoneyUtils.round(subtotal * 0.10);
375	        }
376	
377	        if (coupon.equals("MINUS50")) {
378	            if (subtotal < 300) {
379	                return 0;
380	            }
381	            return 50.0;
382	        }
383	
384	        if (coupon.equals("FREESHIPPING")) {
385	            if (req.shippingMethod.equals("STORE_PICKUP")) {
386	                return 0;
387	            }
388	            ShippingInfo shipping = calculateShipping(req);
389	            if (shipping == null) {
390	                return 0;
391	            }
392	            return shipping.cost;
393	        }
394	
395	        if (coupon.equals("BUY3PAY2")) {
396	            double discount = 0;
397	            for (CheckoutRequest.OrderItemData item : req.items) {
398	                Product product = ProductService.getProduct(item.sku);
399	                int freeUnits = item.quantity / 3;
400	                discount += product.price * freeUnits;
401	            }
402	            return MoneyUtils.round(discount);
403	        }
404	
405	        return 0;
406	    }
407	
408	    private static boolean hasCompletedOrder(String cpf) throws SQLException {
409	        String sql = "SELECT COUNT(*) as count FROM orders WHERE cpf = ? AND (status = 'PAID' OR status = 'SHIPPED' OR status = 'DELIVERED')";
410	        java.sql.Connection conn = Database.getDataSource().getConnection();
411	        java.sql.PreparedStatement pstmt = conn.prepareStatement(sql);
412	        pstmt.setString(1, cpf);
413	        java.sql.ResultSet rs = pstmt.executeQuery();
414	        rs.next();
415	        int count = rs.getInt("count");
416	        rs.close();
417	        pstmt.close();
418	        conn.close();
419	        return count > 0;
420	    }
421	
422	    private static ShippingInfo calculateShipping(CheckoutRequest req) throws SQLException {
423	        Enums.ShippingMethod method = Enums.ShippingMethod.valueOf(req.shippingMethod);
424	
425	        double totalWeight = 0;
426	        for (CheckoutRequest.OrderItemData item : req.items) {
427	            Product product = ProductService.getProduct(item.sku);
428	            totalWeight += product.weightKg * item.quantity;
429	        }
430	
431	        if (method == Enums.ShippingMethod.STORE_PICKUP) {
432	            return new ShippingInfo(0, 1);
433	        }
434	
435	        if (method == Enums.ShippingMethod.COURIER) {
436	            if (totalWeight > MAX_COURIER_WEIGHT) {
437	                return null;
438	            }
439	            return new ShippingInfo(18.0, 0);
440	        }
441	
442	        String translogUrl = System.getenv("TRANSLOG_URL");
443	        if (translogUrl == null || translogUrl.isEmpty()) {
444	            return null;
445	        }
446	
447	        String service = method == Enums.ShippingMethod.ECONOMY ? "STD" : "EXP";
448	        int weightGrams = (int) (totalWeight * 1000);
449	
450	        TranslogResponse response = queryTranslog(translogUrl, req.zipCode, weightGrams, service);
451	        if (response == null) {
452	            return null;
453	        }
454	
455	        if (response.error != null) {
456	            return null;
457	        }
458	
459	        double costReais = response.priceCents / 100.0;
460	        int daysBase = (int) Math.ceil(response.etaHours / 24.0);
461	
462	        Enums.Region region = Enums.Region.valueOf(req.region);
463	        int daysExtra = 0;
464	        if (region == Enums.Region.NORTH) {
465	            daysExtra = 3;
466	        } else if (region == Enums.Region.NORTHEAST) {
467	            daysExtra = 2;
468	        }
469	
470	        return new ShippingInfo(costReais, daysBase + daysExtra);
471	    }
472	
473	    private static TranslogResponse queryTranslog(String baseUrl, String zipCode, int weightGrams, String service) {
474	        try {
475	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s", baseUrl, zipCode, weightGrams, service);
476	            java.net.HttpURLConnection conn = (java.net.HttpURLConnection) new java.net.URL(url).openConnection();
477	            conn.setRequestMethod("GET");
478	            conn.setConnectTimeout(2000);
479	            conn.setReadTimeout(2000);
480	
481	            int status = conn.getResponseCode();
482	            if (status != 200) {
483	                return null;
484	            }
485	
486	            String response = new String(conn.getInputStream().readAllBytes());
487	            com.google.gson.JsonElement element = com.google.gson.JsonParser.parseString(response);
488	            com.google.gson.JsonObject obj = element.getAsJsonObject();
489	
490	            if (obj.has("error")) {
491	                TranslogResponse resp = new TranslogResponse();
492	                resp.error = obj.get("error").getAsString();
493	                return resp;
494	            }
495	
496	            TranslogResponse resp = new TranslogResponse();
497	            resp.priceCents = obj.get("price_cents").getAsInt();
498	            resp.etaHours = obj.get("eta_hours").getAsInt();
499	            return resp;
500	        } catch (Exception e) {
501	            return null;
502	        }
503	    }
504	
505	    private static double calculateInsurance(CheckoutRequest req, double subtotal) {
506	        Enums.Region region = Enums.Region.valueOf(req.region);
507	        double percentage = 0;
508	        double limit = Double.MAX_VALUE;
509	
510	        switch (region) {
511	            case SOUTHEAST, SOUTH -> percentage = 0.01;
512	            case MIDWEST -> percentage = 0.015;
513	            case NORTH -> {
514	                percentage = 0.025;
515	                limit = 30.0;
516	            }
517	            case NORTHEAST -> {
518	                percentage = 0.02;
519	                limit = 30.0;
520	            }
521	        }
522	
523	        double insurance = MoneyUtils.round(subtotal * percentage);
524	        if (insurance > limit) {
525	            insurance = limit;
526	        }
527	        return insurance;
528	    }
529	
530	    private static boolean isInstallmentsValid(String paymentMethod, int installments) {
531	        if (installments < 1 || installments > 12) {
532	            return false;
533	        }
534	        if (paymentMethod.equals("PIX") || paymentMethod.equals("BANK_SLIP")) {
535	            return installments == 1;
536	        }
537	        return true;
538	    }
539	
540	    private static boolean isCouponValid(String coupon) {
541	        return coupon.equals("WELCOME10") || coupon.equals("MINUS50") ||
542	               coupon.equals("FREESHIPPING") || coupon.equals("BUY3PAY2");
543	    }
544	
545	    public static class ValidationError {
546	        public String code;
547	        public int httpStatus;
548	
549	        public ValidationError(String code, int httpStatus) {
550	            this.code = code;
551	            this.httpStatus = httpStatus;
552	        }
553	    }
554	
555	    private static class ShippingInfo {
556	        double cost;
557	        int days;
558	
559	        ShippingInfo(double cost, int days) {
560	            this.cost = cost;
561	            this.days = days;
562	        }
563	    }
564	
565	    private static class TranslogResponse {
566	        int priceCents;
567	        int etaHours;
568	        String error;
569	    }
570	}

