 65	    public static Order getOrder(String orderId) throws SQLException {
 66	        String sql = """
 67	            SELECT id, cpf, status, created_at, products_subtotal, coupon_discount, shipping_cost,
 68	                   delivery_days, insurance, payment_adjustment, final_total, installments,
 69	                   installment_amount, next_purchase_credit, gift, tracking_code
 70	            FROM orders WHERE id = ?
 71	            """;
 72	
 73	        try (Connection conn = Database.getDataSource().getConnection();
 74	             PreparedStatement pstmt = conn.prepareStatement(sql)) {
 75	            pstmt.setString(1, orderId);
 76	            ResultSet rs = pstmt.executeQuery();
 77	
 78	            if (!rs.next()) {
 79	                return null;
 80	            }
 81	
 82	            OrderSummary summary = new OrderSummary(
 83	                rs.getDouble("products_subtotal"),
 84	                rs.getDouble("coupon_discount"),
 85	                rs.getDouble("shipping_cost"),
 86	                rs.getInt("delivery_days"),
 87	                rs.getDouble("insurance"),
 88	                rs.getDouble("payment_adjustment"),
 89	                rs.getDouble("final_total"),
 90	                rs.getInt("installments"),
 91	                rs.getDouble("installment_amount"),
 92	                rs.getDouble("next_purchase_credit"),
 93	                rs.getBoolean("gift")
 94	            );
 95	
 96	            List<OrderItem> items = getOrderItems(orderId);
 97	
 98	            String trackingCode = rs.getString("tracking_code");
 99	
100	            return new Order(
101	                rs.getString("id"),
102	                Enums.OrderStatus.valueOf(rs.getString("status")),
103	                rs.getObject("created_at", java.time.Instant.class),
104	                summary,
105	                items,
106	                trackingCode
107	            );
108	        }
109	    }
110	
111	    private static List<OrderItem> getOrderItems(String orderId) throws SQLException {
