410	import com.loja.models.*;
411	
412	import java.sql.*;
413	import java.util.*;
414	
415	public class Database {
416	    private static HikariDataSource dataSource;
417	
418	    public static void init(String dbUrl, String dbUser, String dbPassword) throws SQLException {
419	        HikariConfig config = new HikariConfig();
420	        config.setJdbcUrl(dbUrl);
421	        config.setUsername(dbUser);
422	        config.setPassword(dbPassword);
423	        config.setMaximumPoolSize(10);
424	        dataSource = new HikariDataSource(config);
425	
426	        migrate();
427	    }
428	
429	    private static void migrate() throws SQLException {
430	        try (Connection conn = dataSource.getConnection()) {
431	            Statement stmt = conn.createStatement();
432	
433	            stmt.execute("""
434	                CREATE TABLE IF NOT EXISTS products (
435	                    sku VARCHAR(20) PRIMARY KEY,
436	                    name VARCHAR(255) NOT NULL,
437	                    price DECIMAL(10, 2) NOT NULL,
438	                    weight_kg DECIMAL(5, 2) NOT NULL,
439	                    stock INT NOT NULL,
440	                    discontinued BOOLEAN NOT NULL DEFAULT FALSE
441	                )
442	                """);
443	
444	            stmt.execute("""
445	                CREATE TABLE IF NOT EXISTS customers (
446	                    cpf VARCHAR(11) PRIMARY KEY,
447	                    email VARCHAR(255) NOT NULL,
448	                    credit_balance DECIMAL(10, 2) NOT NULL DEFAULT 0.00
449	                )
450	                """);
451	
452	            stmt.execute("""
453	                CREATE TABLE IF NOT EXISTS orders (
454	                    id VARCHAR(36) PRIMARY KEY,
455	                    cpf VARCHAR(11) NOT NULL REFERENCES customers(cpf),
456	                    email VARCHAR(255) NOT NULL,
457	                    status VARCHAR(30) NOT NULL,
458	                    created_at TIMESTAMP NOT NULL,
459	                    products_subtotal DECIMAL(10, 2) NOT NULL,
460	                    coupon_discount DECIMAL(10, 2) NOT NULL,
461	                    shipping_cost DECIMAL(10, 2) NOT NULL,
462	                    delivery_days INT NOT NULL,
463	                    insurance DECIMAL(10, 2) NOT NULL,
464	                    payment_adjustment DECIMAL(10, 2) NOT NULL,
465	                    final_total DECIMAL(10, 2) NOT NULL,
466	                    installments INT NOT NULL,
467	                    installment_amount DECIMAL(10, 2) NOT NULL,
468	                    next_purchase_credit DECIMAL(10, 2) NOT NULL,
469	                    gift BOOLEAN NOT NULL,
470	                    tracking_code VARCHAR(50),
471	                    region VARCHAR(20) NOT NULL,
472	                    shipping_method VARCHAR(20) NOT NULL,
473	                    payment_method VARCHAR(20) NOT NULL,
474	                    club_tier VARCHAR(10) NOT NULL,
475	                    coupon VARCHAR(50),
476	                    paid_at TIMESTAMP,
477	                    payment_transaction_id VARCHAR(100)
478	                )
479	                """);
480	
481	            stmt.execute("""
482	                CREATE TABLE IF NOT EXISTS order_items (
483	                    id SERIAL PRIMARY KEY,
484	                    order_id VARCHAR(36) NOT NULL REFERENCES orders(id),
485	                    sku VARCHAR(20) NOT NULL REFERENCES products(sku),
486	                    quantity INT NOT NULL
487	                )
488	                """);
489	
490	            stmt.execute("""
491	                CREATE TABLE IF NOT EXISTS notifications (
492	                    id VARCHAR(36) PRIMARY KEY,
